service AgentService {
    rpc Process(ProcessRequest)
        returns (ProcessResponse);

    rpc GetStatus(StatusRequest)
        returns (StatusResponse);
}

# External entry point
POST http://localhost:8000/process
Content-Type: application/json
{ "text": "What is quantum computing?" }

# LLM returns a pure JSON workflow plan
analysis_prompt = f"""
Return a pure JSON object:
{{
  "task_type": "RESEARCH|COMPUTATION|SUMMARIZATION|COMPOUND",
  "steps": [
    {{
      "agent": "perplexity|math|summarization",
      "input": "specific instruction",
      "depends_on": []   # valid previous step indices only
    }}
  ]
}}
"""
response = await self._call_llm(analysis_prompt)
analysis  = json.loads(response.text)

# Sanitise dependencies before building WorkflowSteps
for i, step in enumerate(analysis["steps"]):
    step["depends_on"] = [
        dep for dep in step.get("depends_on", [])
        if isinstance(dep, int) and 0 <= dep < i
    ]

workflow_steps = [
    WorkflowStep(s["agent"], s["input"], s["depends_on"])
    for s in analysis["steps"]
]

# Collect steps whose dependencies are satisfied
pending_steps = [
    (i, step, clients[step.agent_type], resolved_input)
    for i, step in enumerate(workflow_steps)
    if not step.completed and all(
        workflow_steps[dep].completed
        for dep in step.depends_on
    )
]

# Dispatch the entire group concurrently
tasks = [
    client.process(input_text)
    for _, step, client, input_text in pending_steps
]
results = await asyncio.gather(*tasks, return_exceptions=True)

for (i, step, _, _), result in zip(pending_steps, results):
    if isinstance(result, Exception):
        raise result
    step.output    = result
    step.completed = True

# {STEP_N} placeholders in later steps are
# replaced with the output of step N before dispatch

