# CLIENT (agent_client.py)
class AgentClient:
    def __init__(self, address: str):
        self.channel = grpc.aio.insecure_channel(address)
        self.stub = AgentServiceStub(self.channel)

    async def process(self, input_text: str) -> str:
        req = ProcessRequest(input_text=input_text)
        resp = await self.stub.Process(req)
        if not resp.success:
            raise Exception(resp.error_message)
        return resp.output_text

    async def health_check(self) -> bool:          # 3 retries, 1 s apart
        for attempt in range(3):
            try:
                resp = await self.stub.GetStatus(
                    StatusRequest(agent_name="health_check")
                )
                return resp.status == "SERVING"
            except grpc.aio.AioRpcError:
                if attempt == 2: return False
                await asyncio.sleep(1)

# SERVER (agent_service.py)
class AgentService(AgentServiceServicer):
    async def Process(self, request, context):
        result = await self.agent.process(request.input_text)
        return ProcessResponse(success=True, output_text=result)

    async def GetStatus(self, request, context):
        return StatusResponse(agent_name=self.agent.config.name,
                              status="SERVING")

